import type { SupabaseClient } from '@supabase/supabase-js';
import type { DistrictCourseContent } from '@/lib/studio/courseContent';
import { DISTRICT_COURSE_SLUG } from '@/lib/studio/courseContent';

/** Создаёт или обновляет строку courses в Supabase, связанную с Sanity. Без seed уроков. */
export async function ensureDistrictCourseRecord(
  admin: SupabaseClient,
  content: DistrictCourseContent | null,
): Promise<number | null> {
  const slug = content?.slug ?? DISTRICT_COURSE_SLUG;
  const title = content?.title ?? 'Курс District';
  const description =
    content?.description ??
    'Полная подготовка к ЦТ по математике: от диагностики до пробного экзамена.';
  const sanityId = content?.sanityId ?? null;
  const now = new Date().toISOString();

  const { data: bySanity } = sanityId
    ? await admin.from('courses').select('id').eq('sanity_id', sanityId).maybeSingle()
    : { data: null };

  const { data: bySlug } = await admin
    .from('courses')
    .select('id, sanity_id')
    .eq('slug', slug)
    .maybeSingle();

  const existingId = (bySanity?.id ?? bySlug?.id) as number | undefined;

  if (existingId) {
    const { error } = await admin
      .from('courses')
      .update({
        title,
        slug,
        description,
        sanity_id: sanityId ?? bySlug?.sanity_id ?? null,
        is_active: content?.publicationStatus !== 'archived',
        updated_at: now,
      })
      .eq('id', existingId);
    if (error) throw error;
    if (content) {
      const { syncCourseStaffFromContent } = await import('./course-staff');
      await syncCourseStaffFromContent(admin, existingId, content, { courseSlug: slug }).catch(
        (e) => console.warn('[course-record] staff sync failed:', e),
      );
    }
    return existingId;
  }

  const { data: inserted, error: insertError } = await admin
    .from('courses')
    .insert({
      title,
      slug,
      description,
      sanity_id: sanityId,
      is_active: content?.publicationStatus !== 'archived',
      updated_at: now,
    })
    .select('id')
    .single();
  if (insertError) throw insertError;
  const newId = inserted.id as number;
  if (content) {
    const { syncCourseStaffFromContent } = await import('./course-staff');
    await syncCourseStaffFromContent(admin, newId, content, { courseSlug: slug }).catch((e) =>
      console.warn('[course-record] staff sync failed:', e),
    );
  }
  return newId;
}

export async function resolveCourseIdForContent(
  admin: SupabaseClient,
  content: DistrictCourseContent | null,
): Promise<number | null> {
  try {
    return await ensureDistrictCourseRecord(admin, content);
  } catch {
    const { data } = await admin
      .from('courses')
      .select('id')
      .eq('slug', DISTRICT_COURSE_SLUG)
      .maybeSingle();
    return (data?.id as number) ?? null;
  }
}

/** Быстрый lookup id без UPDATE на каждый запрос кабинета. */
export async function lookupCourseIdsBySlugs(
  admin: SupabaseClient,
  slugs: string[],
): Promise<Map<string, number>> {
  const unique = [...new Set(slugs.filter(Boolean))];
  const map = new Map<string, number>();
  if (unique.length === 0) return map;

  const { data, error } = await admin.from('courses').select('id, slug').in('slug', unique);
  if (error) throw error;
  for (const row of data ?? []) {
    if (row.slug && row.id != null) map.set(row.slug as string, row.id as number);
  }
  return map;
}

/**
 * Курсы для админ-списка: только те, что есть в Sanity (не «призраки» из Supabase).
 * Сейчас — district course; при отсутствии Sanity — пустой список (не показываем stale DB).
 */
export async function listCoursesPresentInSanity(
  admin: SupabaseClient,
): Promise<Array<{ id: number; title: string; slug: string; description: string | null; is_active: boolean; created_at: string; updated_at: string }>> {
  const { listDistrictCourseSummaries } = await import('@/lib/studio/courseContent');
  const summaries = await listDistrictCourseSummaries().catch(() => []);
  if (summaries.length === 0) return [];

  const slugs = summaries.map((s) => s.slug);
  const idBySlug = await lookupCourseIdsBySlugs(admin, slugs);
  const ids = [...idBySlug.values()];
  if (ids.length === 0) return [];

  const { data, error } = await admin
    .from('courses')
    .select('id, title, slug, description, is_active, created_at, updated_at')
    .in('id', ids)
    .order('title', { ascending: true });
  if (error) throw error;
  return (data ?? []) as Array<{
    id: number;
    title: string;
    slug: string;
    description: string | null;
    is_active: boolean;
    created_at: string;
    updated_at: string;
  }>;
}
